import{_ as d,o as e,c as o,a2 as c}from"./chunks/framework.CvydjLy7.js";const p=JSON.parse('{"title":"九、常见问题速查表","description":"","frontmatter":{"title":"九、常见问题速查表"},"headers":[],"relativePath":"ch07/09.md","filePath":"ch07/09.md","lastUpdated":1789497795000}'),r={name:"ch07/09.md"};function a(i,t,s,n,l,u){return e(),o("div",null,[...t[0]||(t[0]=[c('<h1 id="九、常见问题速查表" tabindex="-1">九、常见问题速查表 <a class="header-anchor" href="#九、常见问题速查表" aria-label="Permalink to &quot;九、常见问题速查表&quot;">​</a></h1><table tabindex="0"><thead><tr><th>症状</th><th>原因与解法</th></tr></thead><tbody><tr><td>注解都写了但缓存不生效</td><td><code>@EnableCaching</code> 漏了；或方法被自调用绕过了代理（2.10）</td></tr><tr><td>启动报 <code>No qualifying bean of type &#39;RestClient$Builder&#39;</code></td><td>缺 <code>spring-boot-restclient</code> 依赖（4.3，Boot 4 已从 autoconfigure 拆出）</td></tr><tr><td>缓存名写错，但没有报错</td><td>Caffeine 按需创建不报错；配了 <code>cache-names</code> 时用未声明的名字才会失败（2.5）</td></tr><tr><td>改了数据但页面还是旧值</td><td>写方法漏 <code>@CacheEvict</code>；或 <code>cacheNames</code> / <code>key</code> 不匹配（2.12 的排查顺序）</td></tr><tr><td>缓存条目只增不减</td><td>用了 simple provider，或者 Caffeine 的 <code>spec</code> 里没写 <code>maximumSize</code>（2.2）</td></tr><tr><td>缓存里存的是实体，出现奇怪的不一致</td><td>缓存值应该是不可变 DTO，不是 JPA 实体（2.8）</td></tr><tr><td>多实例部署时数据不一致</td><td>本地缓存跨实例不共享，需要 Redis（2.11）</td></tr><tr><td><code>@RequestParam</code> 上的 <code>@Min</code> 不生效</td><td>控制器类上缺 <code>@Validated</code>（3.2）</td></tr><tr><td>校验错误只报第一个字段</td><td>全局异常处理器里没用 <code>getFieldErrors()</code> 全量收集（3.4）</td></tr><tr><td>校验消息返回了 <code>{xxx}</code> 原文</td><td>消息 key 在 <code>messages.properties</code> 里找不到（3.9）</td></tr><tr><td>自定义约束把“必填”也管了</td><td><code>isValid</code> 里 <code>null</code> 应当直接返回 <code>true</code>（3.6）</td></tr><tr><td>配置配错但启动没报错</td><td>配置类缺 <code>@Validated</code>；光写约束注解不生效（3.8）</td></tr><tr><td><code>read-timeout=3</code> 导致所有请求超时</td><td>Duration 裸数字按<strong>毫秒</strong>解析，必须带单位（第五节）</td></tr><tr><td>外部接口超时变成 500</td><td>没有单独 catch <code>ResourceAccessException</code>，应该转 502（4.6）</td></tr><tr><td>想缓存列表接口但命中率极低</td><td>参数组合发散，不该缓存（2.6）</td></tr><tr><td>定时任务“到点了没执行”</td><td><code>TaskScheduler</code> 默认单线程，被前面的任务占住了（6.1）</td></tr><tr><td>定时任务执行时间飘忽</td><td>用了 <code>fixedRate</code>，改成 <code>fixedDelay</code>（6.2）</td></tr><tr><td>集群里同一个任务跑了三次</td><td><code>@Scheduled</code> 每实例各跑一份，需要分布式锁或 Quartz（6.4）</td></tr><tr><td><code>@Scheduled</code> 方法里的缓存注解不生效</td><td>自调用绕过代理（6.5）</td></tr><tr><td>邮件发送把线程卡死</td><td>SMTP 超时默认是无限的，三个 timeout 都要设（7.2）</td></tr><tr><td>重启后 Quartz 的触发器全没了</td><td><code>initialize-schema: always</code> 的标准脚本会删表，生产要改 <code>never</code>（第八节）</td></tr></tbody></table><blockquote><p><strong>下一篇要做什么</strong></p><p>到这里，单体的读、写、缓存、外部依赖都讲完了。第 8 篇处理“服务之间怎么对话”：用 Kafka 做异步事件、用 AMQP 做任务分发、用 WebSocket 做服务端推送。同样会延续本篇的做法——每个概念都落到案例工程里能跑起来，实测结果说话。</p></blockquote>',3)])])}const _=d(r,[["render",a]]);export{p as __pageData,_ as default};
